// EnvironmentConfiguration: UnitConfig (for ProductionUnitEnvCP)
function apply_UnitConfig(parent, systemModel) {
  parent.standbyPos = new ECP_StandbyPositionEnvCP('standbyPos');
  parent.transElevator = new ECP_TransElevatorEnvCP('transElevator');
  parent.arrivalStock = new ECP_ArrivalStockEnvCP('arrivalStock');
  parent.entryStock = new ECP_SharedEntryStockEnvCP('entryStock');
  parent.departureStock = new ECP_SharedDepartureStockEnvCP('departureStock');
  parent.navLine = new ECP_NavigationLineEnvCP('navLine');
  parent.navPad = new ECP_NavigationPadEnvCP('navPad');
  parent.machineZone = new ECP_RestrictedMachineZoneEnvCP('machineZone');
  parent.obstacle = new ECP_ObstacleEnvCP('obstacle');
  // System component: unit_camera : SysADL.Components.CameraSensorCP
  parent.unit_camera = systemModel ? systemModel.getComponentByType('SysADL.Components.CameraSensorCP', 'unit_camera') : { name: 'unit_camera', type: 'SysADL.Components.CameraSensorCP' };
  // System component: unit_obstacleSens : SysADL.Components.ObstacleSensorCP
  parent.unit_obstacleSens = systemModel ? systemModel.getComponentByType('SysADL.Components.ObstacleSensorCP', 'unit_obstacleSens') : { name: 'unit_obstacleSens', type: 'SysADL.Components.ObstacleSensorCP' };
  // System component: unit_driveSys : SysADL.Components.DriveSystemCP
  parent.unit_driveSys = systemModel ? systemModel.getComponentByType('SysADL.Components.DriveSystemCP', 'unit_driveSys') : { name: 'unit_driveSys', type: 'SysADL.Components.DriveSystemCP' };
  // System component: unit_grabber : SysADL.Components.GrabberCP
  parent.unit_grabber = systemModel ? systemModel.getComponentByType('SysADL.Components.GrabberCP', 'unit_grabber') : { name: 'unit_grabber', type: 'SysADL.Components.GrabberCP' };
  // Delegation: inUnitTransferFromSPD → entryStock.inPieceColor
  if (parent.envPorts['inUnitTransferFromSPD'] && parent.entryStock && parent.entryStock.envPorts['inPieceColor']) {
    parent.envPorts['inUnitTransferFromSPD'].bindToPort(parent.entryStock.envPorts['inPieceColor']);
  }
  // Delegation: inSPEPresence → entryStock.inPresence
  if (parent.envPorts['inSPEPresence'] && parent.entryStock && parent.entryStock.envPorts['inPresence']) {
    parent.envPorts['inSPEPresence'].bindToPort(parent.entryStock.envPorts['inPresence']);
  }
  // Delegation: inTPresence → transElevator.inPresence
  if (parent.envPorts['inTPresence'] && parent.transElevator && parent.transElevator.envPorts['inPresence']) {
    parent.envPorts['inTPresence'].bindToPort(parent.transElevator.envPorts['inPresence']);
  }
  // Delegation: inTPieceColor → transElevator.inPieceColor
  if (parent.envPorts['inTPieceColor'] && parent.transElevator && parent.transElevator.envPorts['inPieceColor']) {
    parent.envPorts['inTPieceColor'].bindToPort(parent.transElevator.envPorts['inPieceColor']);
  }
  // Delegation: departureStock.outTransferToSPE → outUnitTransferToSPE
  if (parent.departureStock && parent.departureStock.envPorts['outTransferToSPE'] && parent.envPorts['outUnitTransferToSPE']) {
    parent.departureStock.envPorts['outTransferToSPE'].bindToPort(parent.envPorts['outUnitTransferToSPE']);
  }
  // Delegation: navLine.outColor → outUnitNavLine
  if (parent.navLine && parent.navLine.envPorts['outColor'] && parent.envPorts['outUnitNavLine']) {
    parent.navLine.envPorts['outColor'].bindToPort(parent.envPorts['outUnitNavLine']);
  }
  // Delegation: navPad.outColor → outUnitNavPad
  if (parent.navPad && parent.navPad.envPorts['outColor'] && parent.envPorts['outUnitNavPad']) {
    parent.navPad.envPorts['outColor'].bindToPort(parent.envPorts['outUnitNavPad']);
  }
  // Delegation: transElevator.outPieceColor → outUnitPieceColor
  if (parent.transElevator && parent.transElevator.envPorts['outPieceColor'] && parent.envPorts['outUnitPieceColor']) {
    parent.transElevator.envPorts['outPieceColor'].bindToPort(parent.envPorts['outUnitPieceColor']);
  }
  // Delegation: entryStock.outPieceColor → outSPEPieceColor
  if (parent.entryStock && parent.entryStock.envPorts['outPieceColor'] && parent.envPorts['outSPEPieceColor']) {
    parent.entryStock.envPorts['outPieceColor'].bindToPort(parent.envPorts['outSPEPieceColor']);
  }
  // Delegation: arrivalStock.outPieceColor → outSAPieceColor
  if (parent.arrivalStock && parent.arrivalStock.envPorts['outPieceColor'] && parent.envPorts['outSAPieceColor']) {
    parent.arrivalStock.envPorts['outPieceColor'].bindToPort(parent.envPorts['outSAPieceColor']);
  }
  // Delegation: departureStock.outPieceColor → outSPDPieceColor
  if (parent.departureStock && parent.departureStock.envPorts['outPieceColor'] && parent.envPorts['outSPDPieceColor']) {
    parent.departureStock.envPorts['outPieceColor'].bindToPort(parent.envPorts['outSPDPieceColor']);
  }
  // Delegation: standbyPos.outColor → outUnitPAColor
  if (parent.standbyPos && parent.standbyPos.envPorts['outColor'] && parent.envPorts['outUnitPAColor']) {
    parent.standbyPos.envPorts['outColor'].bindToPort(parent.envPorts['outUnitPAColor']);
  }
  // Delegation: obstacle.outObstacle → outObstacle
  if (parent.obstacle && parent.obstacle.envPorts['outObstacle'] && parent.envPorts['outObstacle']) {
    parent.obstacle.envPorts['outObstacle'].bindToPort(parent.envPorts['outObstacle']);
  }
  // EnvConnector: lineC : NavColorEnvCN bindings navLine.outColor = unit_camera.inFloorColor
  parent.lineC = { type: 'NavColorEnvCN', source: 'navLine.outColor', target: 'unit_camera.inFloorColor' };
  // EnvConnector: offsetC : IntEnvCN bindings navLine.outColor = unit_camera.inLineOffset
  parent.offsetC = { type: 'IntEnvCN', source: 'navLine.outColor', target: 'unit_camera.inLineOffset' };
  // EnvConnector: zoneC : ReadPresenceEnvCN bindings machineZone.outPresence = unit_camera.inZoneAlarm
  parent.zoneC = { type: 'ReadPresenceEnvCN', source: 'machineZone.outPresence', target: 'unit_camera.inZoneAlarm' };
  // EnvConnector: colorC : ReadPieceColorEnvCN bindings transElevator.outPieceColor = unit_camera.inPieceColor
  parent.colorC = { type: 'ReadPieceColorEnvCN', source: 'transElevator.outPieceColor', target: 'unit_camera.inPieceColor' };
  // EnvConnector: speColorC : ReadPieceColorEnvCN bindings entryStock.outPieceColor = unit_camera.inPieceColor
  parent.speColorC = { type: 'ReadPieceColorEnvCN', source: 'entryStock.outPieceColor', target: 'unit_camera.inPieceColor' };
  // EnvConnector: spePresenceC : ReadPresenceEnvCN bindings entryStock.outPresence = unit_camera.inZoneAlarm
  parent.spePresenceC = { type: 'ReadPresenceEnvCN', source: 'entryStock.outPresence', target: 'unit_camera.inZoneAlarm' };
  // EnvConnector: obsC : BooleanEnvCN bindings obstacle.outObstacle = unit_obstacleSens.inObstacle
  parent.obsC = { type: 'BooleanEnvCN', source: 'obstacle.outObstacle', target: 'unit_obstacleSens.inObstacle' };
  // EnvConnector: navLineC : SendEnvironmentalDirectionEnvCN bindings unit_driveSys.outColor = navLine.inColor
  parent.navLineC = { type: 'SendEnvironmentalDirectionEnvCN', source: 'unit_driveSys.outColor', target: 'navLine.inColor' };
  // EnvConnector: navPadC : SendEnvironmentalDirectionEnvCN bindings unit_driveSys.outColor = navPad.inColor
  parent.navPadC = { type: 'SendEnvironmentalDirectionEnvCN', source: 'unit_driveSys.outColor', target: 'navPad.inColor' };
  // EnvConnector: paColorC : SendEnvironmentalDirectionEnvCN bindings unit_driveSys.outColor = standbyPos.inColor
  parent.paColorC = { type: 'SendEnvironmentalDirectionEnvCN', source: 'unit_driveSys.outColor', target: 'standbyPos.inColor' };
  // EnvConnector: grabC : SendMotorCommandEnvCN bindings unit_grabber.outGrab = transElevator.inCommand
  parent.grabC = { type: 'SendMotorCommandEnvCN', source: 'unit_grabber.outGrab', target: 'transElevator.inCommand' };
  // EnvConnector: grabSPE_C : SendMotorCommandEnvCN bindings unit_grabber.outGrab = entryStock.inCommand
  parent.grabSPE_C = { type: 'SendMotorCommandEnvCN', source: 'unit_grabber.outGrab', target: 'entryStock.inCommand' };
  // EnvConnector: dropSA_CommandC : SendMotorCommandEnvCN bindings unit_grabber.outGrab = arrivalStock.inDropCommand
  parent.dropSA_CommandC = { type: 'SendMotorCommandEnvCN', source: 'unit_grabber.outGrab', target: 'arrivalStock.inDropCommand' };
  // EnvConnector: dropSPD_CommandC : SendMotorCommandEnvCN bindings unit_grabber.outGrab = departureStock.inDropCommand
  parent.dropSPD_CommandC = { type: 'SendMotorCommandEnvCN', source: 'unit_grabber.outGrab', target: 'departureStock.inDropCommand' };
  // EnvConnector: dropSA_PieceC : SendPieceColorEnvCN bindings unit_grabber.outPieceColor = arrivalStock.inPieceColor
  parent.dropSA_PieceC = { type: 'SendPieceColorEnvCN', source: 'unit_grabber.outPieceColor', target: 'arrivalStock.inPieceColor' };
  // EnvConnector: dropSPD_PieceC : SendPieceColorEnvCN bindings unit_grabber.outPieceColor = departureStock.inPieceColor
  parent.dropSPD_PieceC = { type: 'SendPieceColorEnvCN', source: 'unit_grabber.outPieceColor', target: 'departureStock.inPieceColor' };
}

