  parent.unit2ToUnit1TransferC = { type: 'DetectPieceColorEnvCN', source: 'unit2.outUnitTransferToSPE', target: 'unit1.inUnitTransferFromSPD' };
  // EnvConnector: param1C : ReadParameterEnvCN bindings operator1.outParam = r1_pInput.inParam
