// Scenario: Scenario_ObstacleHandling_Unit1
class Scenario_ObstacleHandling_Unit1 extends Scenario {
  constructor(name = 'Scenario_ObstacleHandling_Unit1', opts = {}) {
    super(name, {
      ...opts,
      scenarioType: 'scenario'
    });
    this.sceneSequence = ["SCN_ObstacleStop_Unit1","SCN_ObstacleResume_Unit1"];
  }

  async execute(context) {
    if (!context || !context.scenes) {
      throw new Error('Context with scenes registry is required for scenario execution');
    }

    // Execute scene with logging
    if (context.model?.logger) {
      context.model.logger.logExecution({
        type: 'scene.execution.started',
        name: 'SCN_ObstacleStop_Unit1',
        context: { scenario: this.name },
        trace: { scenario: this.name, sceneName: 'SCN_ObstacleStop_Unit1' }
      });
    }
    const sceneStartTime_SCN_ObstacleStop_Unit1 = Date.now();
    await this.executeScene('SCN_ObstacleStop_Unit1', context);
    if (context.model?.logger) {
      context.model.logger.logExecution({
        type: 'scene.execution.completed',
        name: 'SCN_ObstacleStop_Unit1',
        context: { scenario: this.name },
        trace: { scenario: this.name, sceneName: 'SCN_ObstacleStop_Unit1' },
        metrics: { duration: Date.now() - sceneStartTime_SCN_ObstacleStop_Unit1 }
      });
    }
    if (context.eventScheduler?.notifyScenarioCompleted) {
      context.eventScheduler.notifyScenarioCompleted('SCN_ObstacleStop_Unit1');
    }
    // Execute scene with logging
    if (context.model?.logger) {
      context.model.logger.logExecution({
        type: 'scene.execution.started',
        name: 'SCN_ObstacleResume_Unit1',
        context: { scenario: this.name },
        trace: { scenario: this.name, sceneName: 'SCN_ObstacleResume_Unit1' }
      });
    }
    const sceneStartTime_SCN_ObstacleResume_Unit1 = Date.now();
    await this.executeScene('SCN_ObstacleResume_Unit1', context);
    if (context.model?.logger) {
      context.model.logger.logExecution({
        type: 'scene.execution.completed',
        name: 'SCN_ObstacleResume_Unit1',
        context: { scenario: this.name },
        trace: { scenario: this.name, sceneName: 'SCN_ObstacleResume_Unit1' },
        metrics: { duration: Date.now() - sceneStartTime_SCN_ObstacleResume_Unit1 }
      });
    }
    if (context.eventScheduler?.notifyScenarioCompleted) {
      context.eventScheduler.notifyScenarioCompleted('SCN_ObstacleResume_Unit1');
    }

    return { success: true, message: 'Scenario completed successfully' };
  }
}

