// ScenarioExecution: ScenarioExecution_P0_T_First_Obstacle → ValidationPlan_RobAFIS (mode: once)
class ScenarioExecution_P0_T_First_Obstacle extends ScenarioExecution {
  constructor(name = 'ScenarioExecution_P0_T_First_Obstacle', opts = {}) {
    super(name, {
      ...opts,
      targetScenarios: 'ValidationPlan_RobAFIS',
      mode: 'once'
    });
  }

  async executeAsync(ctx) {
    // Initial assignment
    ctx.unit1.transElevator.pieces[0].outPresence = true;
    // Initial assignment
    ctx.unit1.transElevator.pieces[0].outColor = ctx.PieceColor.Blue;
    // Initial assignment
    ctx.unit1.entryStock.pieces[0].outPresence = false;
    // Initial assignment
    ctx.unit2.transElevator.pieces[0].outPresence = true;
    // Initial assignment
    ctx.unit2.transElevator.pieces[0].outColor = ctx.PieceColor.Blue;
    // Initial assignment
    ctx.unit2.entryStock.pieces[0].outPresence = false;
    // inject StartSimulationSig immediate
    {
      const injectData = {};
      injectData.mission = ctx.MissionParameter.P0;
      injectData.strategy = ctx.StrategyParameter.T_First;
      if (ctx.envActivities) ctx.envActivities.handleSignal('StartSimulationSig', injectData, ctx);
    }
    // inject ObstacleDetectedSig condition
    {
      const injectData = {};
      ctx.scheduler?.scheduleOnCondition('ObstacleDetectedSig', injectData, () => (ctx.unit1.navPad.outColor === ctx.NavColor.Green), '(ctx.unit1.navPad.outColor === ctx.NavColor.Green)');
    }
    // inject ObstacleRemovedSig delay
    {
      const injectData = {};
      ctx.scheduler?.scheduleInject('ObstacleRemovedSig', injectData, 1000);
    }
    // Parallel scenarios execution
    {
      const pResults = await Promise.all([
        (async () => {
          const res = await this.executeScenario('Scenario_RoutingLogic_P0_Unit1', ctx);
          return { scenario: 'Scenario_RoutingLogic_P0_Unit1', result: res };
        })(),
        (async () => {
          const res = await this.executeScenario('Scenario_ObstacleHandling_Unit1', ctx);
          return { scenario: 'Scenario_ObstacleHandling_Unit1', result: res };
        })(),
        (async () => {
          const res = await this.executeScenario('Scenario_EndMission_Unit1', ctx);
          return { scenario: 'Scenario_EndMission_Unit1', result: res };
        })(),
        (async () => {
          const res = await this.executeScenario('Scenario_RoutingLogic_P0_Unit2', ctx);
          return { scenario: 'Scenario_RoutingLogic_P0_Unit2', result: res };
        })(),
        (async () => {
          const res = await this.executeScenario('Scenario_EndMission_Unit2', ctx);
          return { scenario: 'Scenario_EndMission_Unit2', result: res };
        })()
      ]);
      ctx.parallelResults.push(...pResults);
    }
    return { success: true, execution: 'ScenarioExecution_P0_T_First_Obstacle' };
  }
}

