  model.envComponentDefs['ProductionUnitEnvCP'] = ECP_ProductionUnitEnvCP;
  model.envComponentDefs['AtelierEnvironment'] = ECP_AtelierEnvironment;
  
  // Apply boundary component extensions
  model.boundaryExtensions = [];
  model.boundaryExtensions.push(BEX_SysADL_Components_ParameterInputCP);
  model.boundaryExtensions.push(BEX_SysADL_Components_CameraSensorCP);
  model.boundaryExtensions.push(BEX_SysADL_Components_ObstacleSensorCP);
  model.boundaryExtensions.push(BEX_SysADL_Components_DriveSystemCP);
  model.boundaryExtensions.push(BEX_SysADL_Components_GrabberCP);
  
  // EnvActivities
  model.envActivities = new ENVACT_RobAFISEnvironmentActivities();
  
  // Environment configurations
  model.envConfigs = {};
  model.envConfigs['TransElevatorEnvCP'] = apply_TransElevatorConfig;
